exercise.referenceSolution:
#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) {
        return 0;
    }
    int best;
    scanf("%d", &best);
    int position = 1;
    for (int i = 2; i <= n; i++) {
        int value;
        scanf("%d", &value);
        if (value > best) {
            best = value;
            position = i;
        }
    }
    printf("%d %d\n", best, position);
    return 0;
}

