int main(void) {
    long long a, b;
    while (scanf("%lld %lld", &a, &b) == 2) {
        int steps = 0;
        while (b != 0) {
            long long rest = a % b;
            a = b;
            b = rest;
            steps++;
        }
        printf("%lld %d\n", a, steps);
    }
    return 0;
}

