int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) {
        return 0;
    }
    int first;
    scanf("%d", &first);
    int second = 0;
    bool has_second = false;
    for (int i = 1; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x > first) {
            second = first;
            has_second = true;
            first = x;
        } else if (x < first && (!has_second || x > second)) {
            second = x;
            has_second = true;
        }
    }
    if (has_second) {
        printf("%d\n", second);
    } else {
        printf("нет\n");
    }
    return 0;
}

